#!/usr/bin/env python3
"""Generate dot_avx_amd64.s / l2_avx_amd64.s (Weaviate float32 Dot / L2 kernels).

Layout per kernel: a staged short path for lengths below one main-loop trip
(every stage appends to as few accumulator chains as it has blocks, so the
fold depth matches the work), the main loop with C independent FMA chains,
stepped-down tails after the loop, one overlapped masked block for the final
partial vector, and a shuffle/add horizontal reduce (no VHADDPS).
"""

import sys

HEADER = """//go:build amd64

#include "textflag.h"

// Code generated by gen_float_amd64.py in this directory; DO NOT EDIT.
// Regenerate with: python3 gen_float_amd64.py .
"""


def table(sym, lanes_max=16):
    # 16 zero lanes followed by 16 all-ones lanes. For a W-lane load that must
    # keep the last r lanes, load at byte offset (16-W+r)*4.
    out = []
    for i in range(16):
        out.append(f"DATA {sym}<>+{i*4}(SB)/4, $0x00000000")
    for i in range(16, 32):
        out.append(f"DATA {sym}<>+{i*4}(SB)/4, $0xFFFFFFFF")
    out.append(f"GLOBL {sym}<>(SB), RODATA|NOPTR, $128")
    return "\n".join(out) + "\n"


class Gen:
    def __init__(self, op, isa):
        self.op, self.isa = op, isa
        if isa == "avx2":
            self.W, self.C, self.R = 8, 4, "Y"  # lanes, chains, main reg class
        else:
            self.W, self.C, self.R = 16, 8, "Z"
        self.trip = self.W * self.C
        self.lines = []
        self.lbl = 0
        self.mask = f"tailmask_{op}"

    def o(self, s=""):
        self.lines.append(s)

    # ---- building blocks -------------------------------------------------
    def block(self, R, W, off, tmp, acc, masked=False):
        """One W-lane block at byte offset off from AX/CX into accumulator acc.
        tmp: scratch register index. masked: operands come via R8/R9 and
        are ANDed with the mask in register `R10-loaded` tmp+2."""
        xs, ys = (f"(R8)", f"(R9)") if masked else (f"{off}(AX)", f"{off}(CX)")
        t, t2, m = f"{R}{tmp}", f"{R}{tmp+1}", f"{R}{tmp+2}"
        if masked:
            lanes = {4: 12, 8: 8, 16: 0}[W]
            self.o(f"\tLEAQ {self.mask}<>+{lanes*4}(SB), R10")
            self.o(f"\tVMOVUPS (R10)(DX*4), {m}")
            self.o(f"\tVMOVUPS {xs}, {t}")
            self.o(f"\tVMOVUPS {ys}, {t2}")
            andop = "VPANDD" if R == "Z" else "VANDPS"
            self.o(f"\t{andop} {m}, {t}, {t}")
            self.o(f"\t{andop} {m}, {t2}, {t2}")
            if self.op == "dot":
                self.o(f"\tVFMADD231PS {t2}, {t}, {R}{acc}")
            else:
                self.o(f"\tVSUBPS {t2}, {t}, {t}")
                self.o(f"\tVFMADD231PS {t}, {t}, {R}{acc}")
            return
        self.o(f"\tVMOVUPS {xs}, {t}")
        if self.op == "dot":
            self.o(f"\tVFMADD231PS {ys}, {t}, {R}{acc}")
        else:
            self.o(f"\tVSUBPS {ys}, {t}, {t}")
            self.o(f"\tVFMADD231PS {t}, {t}, {R}{acc}")

    def blocks(self, R, W, nblk, accs):
        """nblk consecutive W-lane blocks into accs (round-robin), then advance."""
        tmpbase = self.C
        for i in range(nblk):
            self.block(R, W, i * W * 4, tmpbase + (i % (16 - tmpbase - 2)), accs[i % len(accs)])
        self.o(f"\tADDQ ${nblk*W*4}, AX")
        self.o(f"\tADDQ ${nblk*W*4}, CX")
        self.o(f"\tSUBQ ${nblk*W}, DX")

    def zero(self, R, accs):
        # ZMM VXORPS/VANDPS are AVX512DQ; VPXORD/VPANDD are AVX512F, so the
        # kernel runs wherever HasAVX512 is true.
        op = "VPXORD" if R == "Z" else "VXORPS"
        for a in accs:
            self.o(f"\t{op} {R}{a}, {R}{a}, {R}{a}")

    def fold(self, R, accs):
        """Tree-add accs into accs[0]."""
        accs = list(accs)
        while len(accs) > 1:
            nxt = []
            for i in range(0, len(accs) - 1, 2):
                self.o(f"\tVADDPS {R}{accs[i+1]}, {R}{accs[i]}, {R}{accs[i]}")
                nxt.append(accs[i])
            if len(accs) % 2:
                nxt.append(accs[-1])
            accs = nxt

    def reduce(self, R, acc, vzu=True):
        """Horizontal sum of R{acc} into X0 lane 0, store, return."""
        a = acc
        if R == "Z":
            self.o(f"\tVEXTRACTF64X4 $1, Z{a}, Y{a+1}")
            self.o(f"\tVADDPS Y{a+1}, Y{a}, Y{a}")
            R = "Y"
        if R == "Y":
            self.o(f"\tVEXTRACTF128 $1, Y{a}, X{a+1}")
            self.o(f"\tVADDPS X{a+1}, X{a}, X{a}")
        # 4 lanes in X{a}: (0+1, 2+3) then (01 + 23)
        self.o(f"\tVMOVSHDUP X{a}, X{a+1}")
        self.o(f"\tVADDPS X{a+1}, X{a}, X{a}")
        self.o(f"\tVUNPCKHPD X{a}, X{a}, X{a+1}")
        self.o(f"\tVADDSS X{a+1}, X{a}, X{a}")
        if vzu:
            self.o("\tVZEROUPPER")
        self.o(f"\tMOVSS X{a}, ret+48(FP)")
        self.o("\tRET")

    def opt_stage(self, R, W, nblk, accs, label_next):
        """If DX >= nblk*W: nblk blocks into accs. Falls through either way."""
        self.o(f"\tCMPQ DX, ${nblk*W}")
        self.o(f"\tJL {label_next}")
        self.blocks(R, W, nblk, accs)
        self.o(f"{label_next}:")

    def masked_stage(self, R, W, acc, label_next):
        self.o("\tTESTQ DX, DX")
        self.o(f"\tJE {label_next}")
        self.block(R, W, 0, self.C, acc, masked=True)
        self.o(f"{label_next}:")

    # ---- kernel ------------------------------------------------------------
    def kernel(self):
        name = ("dot" if self.op == "dot" else "l2") + ("AVX2" if self.isa == "avx2" else "AVX512")
        p = name  # label prefix
        R, W, C, trip = self.R, self.W, self.C, self.trip
        minlen = 4 if self.isa == "avx2" else 16
        self.o(f"// func {name}(x, y []float32) float32")
        self.o("//")
        self.o(f"// Requires len(x) >= {minlen} and len(y) >= len(x); see the Go wrapper.")
        self.o(f"TEXT ·{name}(SB), NOSPLIT, $0-52")
        self.o("\tMOVQ x_base+0(FP), AX")
        self.o("\tMOVQ y_base+24(FP), CX")
        self.o("\tMOVQ x_len+8(FP), DX")
        self.o(f"\tCMPQ DX, ${trip}")
        self.o(f"\tJL {p}_short")
        # main path: C chains, trip elements per iteration
        self.o(f"\t// Main path: {C} chains, {trip} elements per trip.")
        self.o(f"\tLEAQ -{W*4}(AX)(DX*4), R8")
        self.o(f"\tLEAQ -{W*4}(CX)(DX*4), R9")
        self.zero(R, range(C))
        self.o(f"{p}_loop:")
        for i in range(C):
            self.block(R, W, i * W * 4, C + i, i)
        self.o(f"\tADDQ ${trip*4}, AX")
        self.o(f"\tADDQ ${trip*4}, CX")
        self.o(f"\tSUBQ ${trip}, DX")
        self.o(f"\tCMPQ DX, ${trip}")
        self.o(f"\tJGE {p}_loop")
        # tails after the loop: halve repeatedly, each into chains of its own
        nb, acc0 = C // 2, 0
        k = 0
        while nb >= 1:
            self.opt_stage(R, W, nb, list(range(acc0, acc0 + nb)), f"{p}_t{k}")
            acc0 += nb
            nb //= 2
            k += 1
        self.masked_stage(R, W, C - 1, f"{p}_fold")
        self.fold(R, range(C))
        self.reduce(R, 0)
        # short paths: lengths in [minlen, trip)
        self.o("")
        self.o(f"\t// Short paths for len(x) < {trip}: each stage accumulates into as")
        self.o("\t// many chains as it has blocks, so the fold is only as deep as the work.")
        self.o(f"{p}_short:")
        self.o(f"\tLEAQ -{W*4}(AX)(DX*4), R8")
        self.o(f"\tLEAQ -{W*4}(CX)(DX*4), R9")
        sizes = []
        n = trip // 2
        while n >= W:
            sizes.append(n)
            n //= 2
        # sizes e.g. avx2: [16, 8]; avx512: [64, 32, 16]
        for idx, sz in enumerate(sizes):
            nxt = (
                f"{p}_s{sizes[idx+1]}"
                if idx + 1 < len(sizes)
                else (f"{p}_s4" if self.isa == "avx2" else None)
            )
            self.o(f"{p}_s{sz}:")
            if nxt:
                self.o(f"\tCMPQ DX, ${sz}")
                self.o(f"\tJL {nxt}")
            nblk = sz // W
            accs = list(range(nblk))
            self.zero(R, accs)
            self.blocks(R, W, nblk, accs)
            # remaining stages append to existing chains
            rem, k, a = nblk // 2, 0, 0
            while rem >= 1:
                self.opt_stage(R, W, rem, list(range(a, a + rem)), f"{p}_s{sz}_t{k}")
                a += rem
                rem //= 2
                k += 1
            self.masked_stage(R, W, nblk - 1, f"{p}_s{sz}_fold")
            self.fold(R, accs)
            self.reduce(R, 0)
        if self.isa == "avx2":
            # [4, 8): one XMM block plus a masked XMM block (last four).
            self.o(f"{p}_s4:")
            self.o("\tLEAQ -16(AX)(DX*4), R8")
            self.o("\tLEAQ -16(CX)(DX*4), R9")
            self.o("\tVXORPS X0, X0, X0")
            self.block("X", 4, 0, C, 0)
            self.o("\tSUBQ $4, DX")
            self.masked_stage("X", 4, 0, f"{p}_s4_fold")
            self.reduce("X", 0, vzu=False)
        return "\n".join(self.lines) + "\n"


def file(op):
    out = [HEADER]
    out.append(
        f"// {Gen(op,'avx2').mask}: 16 zero lanes then 16 all-ones lanes. A W-lane load at byte"
    )
    out.append("// offset (16-W+r)*4 keeps the last r of W lanes.")
    out.append(table(f"tailmask_{op}"))
    for isa in ("avx2", "avx512"):
        out.append(Gen(op, isa).kernel())
    return "\n".join(out)


if __name__ == "__main__":
    dst = sys.argv[1]
    for op in ("dot", "l2"):
        open(f"{dst}/{op}_avx_amd64.s", "w").write(file(op))
